import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Auto-Fetch Blocklists","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/user-guide/auto-fetch.md","filePath":"openshield-xdp/user-guide/auto-fetch.md","lastUpdated":1785937469000}'),n={name:"openshield-xdp/user-guide/auto-fetch.md"};function o(d,e,l,r,h,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="auto-fetch-blocklists" tabindex="-1">Auto-Fetch Blocklists <a class="header-anchor" href="#auto-fetch-blocklists" aria-label="Permalink to &quot;Auto-Fetch Blocklists&quot;">​</a></h1><p>Since v2.2.0, OpenShield can keep your ban list fed automatically: on a configurable interval it downloads threat-intelligence IP feeds — the official <a href="https://github.com/AnAverageBeing/openshield-blocklists" target="_blank" rel="noreferrer">openshield-blocklists</a> categories plus any custom URLs you add — validates and de-duplicates the entries, and loads them straight into the XDP ban maps. Known botnet C2s, scanners, and brute-forcers are dropped at the NIC before they ever produce a suspicion score.</p><p>It&#39;s <strong>on by default</strong> with a 1-hour interval and a curated set of categories. No API keys, no accounts — the feeds are plain text on GitHub.</p><h2 id="what-gets-banned-and-for-how-long" tabindex="-1">What gets banned, and for how long <a class="header-anchor" href="#what-gets-banned-and-for-how-long" aria-label="Permalink to &quot;What gets banned, and for how long&quot;">​</a></h2><ul><li>Each category expands to four feed files (<code>ipv4.txt</code>, <code>ipv6.txt</code>, <code>ipv4-cidrs.txt</code>, <code>ipv6-cidrs.txt</code>) — single IPs go into the ban maps, CIDRs into the LPM subnet-ban maps.</li><li>Fetched bans carry their own reason tag and <strong>expire after 2× the fetch interval</strong> (floor: 10 minutes). A broken or hijacked feed can never block anyone permanently — stale entries age out on their own.</li><li>A feed that fails to download is logged and skipped; if <em>every</em> feed fails, the existing fetched bans are kept until they expire naturally.</li><li>Entries are merged and de-duplicated across all feeds before anything is applied.</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auto_fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # default: true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  interval_sec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # default: 3600 (1h), minimum 60</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vps&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # &quot;vps&quot; (default) or &quot;dedicated&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  categories</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># official feed categories</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">c2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">botnets</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">malware</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scanners</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">abuse</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bruteforce</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ssh-attackers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">credential-stuffing</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">web-exploit-scanners</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">exploited-infrastructure</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">high-risk-networks</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  urls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># extra raw list URLs (one IP/CIDR per line, # comments OK)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  never_block</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># IPs/CIDRs exempt from FETCHED bans only (see warning below)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  provider_urls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># custom provider-range sources for dedicated mode</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>auto_fetch.enabled</code></td><td><code>bool</code></td><td><code>true</code></td><td>Master switch. Toggling applies live — no reload needed</td></tr><tr><td><code>auto_fetch.interval_sec</code></td><td><code>int</code></td><td><code>3600</code></td><td>Seconds between fetch cycles (min <code>60</code>). First fetch runs ~20s after loader start</td></tr><tr><td><code>auto_fetch.mode</code></td><td><code>string</code></td><td><code>&quot;vps&quot;</code></td><td><code>vps</code> or <code>dedicated</code> — see below</td></tr><tr><td><code>auto_fetch.categories</code></td><td><code>[]string</code></td><td>11 categories (above)</td><td>Categories from the official feed repo. Proxy/Tor/VPN categories are deliberately <strong>not</strong> default — they block legit users</td></tr><tr><td><code>auto_fetch.urls</code></td><td><code>[]string</code></td><td><code>[]</code></td><td>Extra http(s) list URLs, one IP/CIDR per line</td></tr><tr><td><code>auto_fetch.never_block</code></td><td><code>[]string</code></td><td><code>[]</code></td><td>IPs/CIDRs the fetcher will never ban</td></tr><tr><td><code>auto_fetch.provider_urls</code></td><td><code>[]string</code></td><td><code>[]</code></td><td>Extra provider-range sources for dedicated mode (plain-text lists or AWS/GCP-style JSON). Empty = built-in defaults</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">never_block is NOT a firewall whitelist</p><p><code>never_block</code> entries are skipped <strong>by the fetcher only</strong>. Those IPs are still fully scored, rate-limited, and banned by the detection engine like anyone else — it just means no auto-fetched feed can ban them. If you want an IP to bypass mitigation entirely, use the <a href="/pingless-studios-docs/openshield-xdp/user-guide/cli#openshield-whitelist-openshield-blacklist">whitelist</a> (<code>sudo openshield wl add &lt;ip&gt;</code>).</p></div><h2 id="mode-vps-vs-dedicated" tabindex="-1">Mode: <code>vps</code> vs <code>dedicated</code> <a class="header-anchor" href="#mode-vps-vs-dedicated" aria-label="Permalink to &quot;Mode: \`vps\` vs \`dedicated\`&quot;">​</a></h2><ul><li><strong><code>vps</code> (default)</strong> — block everything the feeds list. Right for a single server (VPS, game server box, web server) where all inbound traffic is unsolicited anyway.</li><li><strong><code>dedicated</code></strong> — the fetcher skips ranges owned by major cloud/hosting providers (AWS, Azure, GCP, Cloudflare, OVH, Hetzner, …) before applying bans. Use this on dedicated servers that <strong>host VPS clients</strong>: those VMs connect <em>out</em> to cloud providers for updates, APIs, and storage — banning AWS or Cloudflare ranges would sever that outbound connectivity for your customers.</li></ul><p>The provider-range list has built-in defaults (with an offline fallback); <code>provider_urls</code> lets you extend or override it with your own sources. The TUI auto-fetch view shows how many entries were skipped this way (<code>provider_skipped</code>) and how many provider ranges are loaded.</p><h2 id="managing-it-from-the-tui" tabindex="-1">Managing it from the TUI <a class="header-anchor" href="#managing-it-from-the-tui" aria-label="Permalink to &quot;Managing it from the TUI&quot;">​</a></h2><p>Open the access tab (key <code>9</code>) and press <code>f</code> for the auto-fetch view:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Status: ON   Interval: 3600s   Fetches: 14</span></span>
<span class="line"><span>  Last fetch: 03:00:01   Next: 04:00:01</span></span>
<span class="line"><span>  Applied: 48,213 IPs + 1,904 CIDRs from 44 feed files</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>t</code></td><td>Toggle auto-fetch on/off (applies live)</td></tr><tr><td><code>f</code></td><td>Fetch now (runs in the background)</td></tr><tr><td><code>a</code></td><td>Add a never-block entry (IP or CIDR)</td></tr><tr><td><code>d</code></td><td>Remove the selected never-block entry</td></tr><tr><td><code>r</code></td><td>Refresh the status</td></tr><tr><td><code>Esc</code></td><td>Back to the access list</td></tr></tbody></table><h2 id="whitelist-sync" tabindex="-1">Whitelist sync <a class="header-anchor" href="#whitelist-sync" aria-label="Permalink to &quot;Whitelist sync&quot;">​</a></h2><p>Whitelisting an IP does two things automatically: it <strong>unbans</strong> the IP if it&#39;s currently banned, and it <strong>mirrors the entry into <code>auto_fetch.never_block</code></strong> so the fetcher can never re-ban it on the next cycle. Removing it from the whitelist mirrors the removal in <code>never_block</code> too. You don&#39;t need to maintain both lists by hand.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Feed downloads are capped at 64 MB per file with a 45s timeout per feed — a slow mirror can&#39;t stall the pipeline.</li><li>Subnet bans are capped by the LPM trie capacity (4,096 v4 / 2,048 v6 entries); when the trie is full, remaining CIDRs are skipped but single-IP bans (the bulk of the value) still apply.</li><li>Fetcher bans show up in ban lists with their own reason code, so they&#39;re easy to tell apart from manual bans and detection-engine bans.</li></ul><h2 id="what-to-read-next" tabindex="-1">What to read next <a class="header-anchor" href="#what-to-read-next" aria-label="Permalink to &quot;What to read next&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/geo-blocking">Geo Blocking</a> — block whole countries from the TUI</li><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/cli">CLI Reference</a> — manual bans, ban notes, bulk import</li><li><a href="/pingless-studios-docs/openshield-xdp/configuration/reference">Full Config Reference</a></li></ul>`,22)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
